import{_ as r}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as t,o as e,c as l,a3 as i}from"./chunks/framework.D1iekJsc.js";const T=JSON.parse('{"title":"歡迎","description":"MiniTavern Ultra（超迷你酒館）使用手冊：一句話建卡與角色卡 v2/v3，GPT、Claude、OpenRouter 或本機模型，世界書、正則、預設、識圖識人與回覆圖片，備份和聊天存檔。","frontmatter":{"title":"歡迎","description":"MiniTavern Ultra（超迷你酒館）使用手冊：一句話建卡與角色卡 v2/v3，GPT、Claude、OpenRouter 或本機模型，世界書、正則、預設、識圖識人與回覆圖片，備份和聊天存檔。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"歡迎 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra（超迷你酒館）使用手冊：一句話建卡與角色卡 v2/v3，GPT、Claude、OpenRouter 或本機模型，世界書、正則、預設、識圖識人與回覆圖片，備份和聊天存檔。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW"}]]},"headers":[],"relativePath":"zh-TW/index.md","filePath":"zh-TW/index.md","lastUpdated":1792058564000}'),n={name:"zh-TW/index.md"};function o(u,a,d,h,s,g){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="歡迎" tabindex="-1">歡迎 <a class="header-anchor" href="#歡迎" aria-label="Permalink to &quot;歡迎&quot;">​</a></h1><div class="overview-hero"><p><img src="'+r+'" alt="MiniTavern Ultra 功能介面展示"></p></div><h2 id="應用簡介" tabindex="-1">應用簡介 <a class="header-anchor" href="#應用簡介" aria-label="Permalink to &quot;應用簡介&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong>（超迷你酒館）是一款 <strong>AI 角色扮演聊天應用</strong>。</p><p><strong>創造你的夥伴，開始你們的故事</strong>——一句話生成角色卡，或把主流 v2、v3 卡帶進來。</p><p>GPT、Claude、OpenRouter 和家裡的本機模型都能接。金鑰留在手機裡，聊天也優先留在本機。</p><h2 id="你可以做什麼" tabindex="-1">你可以做什麼 <a class="header-anchor" href="#你可以做什麼" aria-label="Permalink to &quot;你可以做什麼&quot;">​</a></h2><ol><li><p><strong>一句話建立角色卡，或帶進 v2 / v3</strong><br> 描述想要的人，生成名稱、人設和開場白，預覽後開聊。見 <a href="/ultra_guides/zh-TW/manual/ai-create">AI 建立</a>。PNG / JSON 對齊主流角色卡 v2、v3，見 <a href="/ultra_guides/zh-TW/manual/chara-card">角色卡</a>。</p></li><li><p><strong>接 GPT、Claude、OpenRouter，或本機模型</strong><br> 自備金鑰直連這些平台，也能接 Ollama / LM Studio。金鑰放在本機安全儲存。見 <a href="/ultra_guides/zh-TW/manual/model-link">模型連線</a>。沒有付費額度時見 <a href="/ultra_guides/zh-TW/free-cloud/">免費雲端</a>；本機部署見 <a href="/ultra_guides/zh-TW/local/">部署本地模型</a>。</p></li><li><p><strong>世界書、正則、預設：建立或匯入</strong><br><a href="/ultra_guides/zh-TW/manual/lorebook">世界書</a> 穩住設定，<a href="/ultra_guides/zh-TW/manual/regex">正則</a> 打磨呈現，<a href="/ultra_guides/zh-TW/manual/presets">預設</a> 換一整套提示詞寫法。都能新建，也能匯入已有檔案。</p></li><li><p><strong>沉浸對話：識圖、識人、回覆圖片</strong><br> 發出的圖能被看懂，也能認出畫面裡的人；角色可以按劇情把圖片回覆進聊天。見 <a href="/ultra_guides/zh-TW/manual/chat">聊天</a>。</p></li><li><p><strong>備份和聊天存檔</strong><br><a href="/ultra_guides/zh-TW/manual/backup">全量備份</a> 換機帶走；<a href="/ultra_guides/zh-TW/manual/chat-archive">聊天存檔</a> 可合併或作為新聊天匯入。</p></li></ol><h2 id="為什麼是-minitavern" tabindex="-1">為什麼是 MiniTavern <a class="header-anchor" href="#為什麼是-minitavern" aria-label="Permalink to &quot;為什麼是 MiniTavern&quot;">​</a></h2><ul><li><strong>建卡很快</strong>：一句話生成，或匯入 v2 / v3</li><li><strong>模型自備</strong>：GPT、Claude、OpenRouter 或本機模型，金鑰留在本機</li><li><strong>長線工具齊</strong>：世界書、正則、預設、人設，建立和匯入都有</li><li><strong>對話能看圖</strong>：識圖、識人、回覆圖片</li><li><strong>資料可帶走</strong>：全量備份與單聊存檔</li></ul><h2 id="快速開始" tabindex="-1">快速開始 <a class="header-anchor" href="#快速開始" aria-label="Permalink to &quot;快速開始&quot;">​</a></h2><ol><li><strong>設定模型</strong>：設定 → <a href="/ultra_guides/zh-TW/manual/model-link">模型</a> → 模型連線 → 新建並測連，設為預設。</li><li><strong>匯入或創造角色</strong>：角色卡 → <a href="/ultra_guides/zh-TW/manual/chara-card">匯入或建立</a>。</li><li><strong>開始聊天</strong>：從角色開聊——陪伴或入戲，由你決定。</li></ol><p>更細步驟見 <a href="/ultra_guides/zh-TW/manual/getting-started">第一次使用</a>。本機部署見 <a href="/ultra_guides/zh-TW/local/">部署本地模型</a> · <a href="/ultra_guides/zh-TW/quickstart">30 分鐘通關</a> · <a href="/ultra_guides/zh-TW/local/image-gen/">生圖</a>。免費額度見 <a href="/ultra_guides/zh-TW/free-cloud/">免費雲端</a>。</p><h2 id="使用手冊入口" tabindex="-1">使用手冊入口 <a class="header-anchor" href="#使用手冊入口" aria-label="Permalink to &quot;使用手冊入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分區</th><th>說明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/zh-TW/manual/">手冊首頁</a></td><td>建議閱讀順序與總覽</td></tr><tr><td><a href="/ultra_guides/zh-TW/manual/model-link">模型</a></td><td>連線、參數、測連與排錯</td></tr><tr><td><a href="/ultra_guides/zh-TW/free-cloud/">免費雲端</a></td><td>各廠商免費額度與填 Key</td></tr><tr><td><a href="/ultra_guides/zh-TW/local/">部署本地模型</a></td><td>語言／生圖本機部署</td></tr><tr><td><a href="/ultra_guides/zh-TW/manual/chara-card">角色</a> · <a href="/ultra_guides/zh-TW/manual/ai-create">AI 創建</a></td><td>匯入、編輯、開聊、用模型生成</td></tr><tr><td><a href="/ultra_guides/zh-TW/manual/chat">聊天</a> · <a href="/ultra_guides/zh-TW/manual/bubbles">氣泡與輸入框</a></td><td>對話、外觀、會話設定</td></tr><tr><td><a href="/ultra_guides/zh-TW/manual/lorebook">進階</a> · <a href="/ultra_guides/zh-TW/manual/presets">預設</a></td><td>世界書、正則、人設、預設</td></tr></tbody></table><p>App 內：設定 → <strong>說明與回饋</strong> → <strong>使用者手冊</strong>。</p><p>下載請用頂欄選單，或前往 <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">產品官網</a>。另見 <a href="/ultra_guides/zh-TW/privacy">隱私協議</a> · <a href="/ultra_guides/zh-TW/terms">服務條款</a>。</p>',17)])])}const _=t(n,[["render",o]]);export{T as __pageData,_ as default};
